create function private.sync_presentation_identity_is_valid_v2(renderer text,revision text) returns boolean
language sql immutable security invoker set search_path='' as $$
 select coalesce((renderer='sync-v1' and revision='8b1fdf1f8637dda23d48ecdaf08e0e5978e2707a')
  or(renderer='sync-onzetrots-v1' and revision='ae83f2b4312408eacae9f29177d3c743e104185b'),false)
$$;

-- Keep the existing YouTube/Engage authorization wrappers in their exact order.
alter function private.assert_sync_slide_before_youtube_v1(uuid,jsonb) rename to assert_sync_slide_before_onzetrots_v1;
create function private.assert_sync_slide_before_youtube_v1(p_tenant_id uuid,p_slide jsonb) returns void
language plpgsql stable security definer set search_path='' as $$
declare clean jsonb;ref jsonb;link text;rows jsonb;
begin
 if p_slide->>'rendererVersion' is distinct from 'sync-onzetrots-v1' then
  perform private.assert_sync_slide_before_onzetrots_v1(p_tenant_id,p_slide);return;
 end if;
 if p_slide is null or pg_column_size(p_slide)>524288 or not extensions.jsonb_matches_schema(private.sync_slide_schema_v1(),p_slide)
 then raise exception 'Approved OnzeTrots structure invalid' using errcode='23514';end if;
 if p_slide#>>'{style,background}'='photo'and not(p_slide->'style'?'backgroundAsset')then raise exception 'Approved photo background missing'using errcode='23514';end if;
 if p_slide#>'{rich,matchday}'is not null and p_slide#>>'{rich,matchday,context,tenantId}'is distinct from p_tenant_id::text then raise exception 'Approved matchday belongs to another tenant'using errcode='23514';end if;
 for ref in select * from private.sites_asset_references_v1(p_slide) loop
  if ref->>'kind'='system' then
   if private.sync_onzetrots_image_manifest_v1()->>(ref->>'path') is distinct from ref->>'checksumSha256'
    and not(ref=p_slide#>'{style,backgroundAsset}' and p_slide#>>'{style,background}'='photo' and exists(select 1 from jsonb_each(private.sync_onzetrots_background_manifest_v1()) entry where entry.key=ref->>'path' and entry.value=to_jsonb(ref->>'checksumSha256')))
   then raise exception 'Approved OnzeTrots image identity invalid' using errcode='23514';end if;
  else perform private.assert_sites_assets_v1(p_tenant_id,ref);end if;
 end loop;
 if exists(select 1 from private.sites_asset_references_v1(p_slide) asset_refs(value) group by asset_refs.value->>'kind',coalesce(asset_refs.value->>'path',asset_refs.value->>'mediaAssetId') having count(distinct asset_refs.value->>'checksumSha256')>1)
 then raise exception 'Conflicting approved image checksums' using errcode='23514';end if;
 for rows in select value from private.sites_json_nodes_v1(p_slide->'rich') where jsonb_typeof(value)='array' and exists(select 1 from jsonb_array_elements(value) item where item?'id') loop
  if jsonb_array_length(rows)<>(select count(distinct item->>'id')from jsonb_array_elements(rows)item)
  then raise exception 'Approved source record identity repeated'using errcode='23514';end if;
 end loop;
 for rows in select value->'rows' from private.sites_json_nodes_v1(p_slide->'rich') where value?'ownTeamId' and value?'rows' loop
  if(select count(*)from jsonb_array_elements(rows)item where item->>'teamId'is not null)<>(select count(distinct item->>'teamId')from jsonb_array_elements(rows)item)
  then raise exception 'Approved team row identity repeated'using errcode='23514';end if;
 end loop;
 for link in select value->>'url'from private.sites_json_nodes_v1(p_slide->'rich')where value?'url'loop
  if link!~*'^https://[^/?#[:space:]@]+([/?#][^[:space:]]*)?$'then raise exception 'Approved public URL invalid'using errcode='23514';end if;
 end loop;
 -- All nested images have been checked. Reuse original flat/poll/URL refinements
 -- with its exact historical identity and no new-system refs in the old allowlist.
 clean:=jsonb_set(jsonb_set(p_slide-array['visual','rich'],'{rendererVersion}','"sync-v1"'),'{sourceRevision}','"8b1fdf1f8637dda23d48ecdaf08e0e5978e2707a"');
 clean:=clean#-'{club,logo}'#-'{home,logo}'#-'{away,logo}'#-'{style,backgroundAsset}';
 if clean#>>'{style,background}'='photo'then clean:=jsonb_set(clean,'{style,background}','"gradient"');end if;
 perform private.assert_sync_slide_before_onzetrots_v1(p_tenant_id,clean);
end;$$;

create or replace function private.assert_sync_dynamic_before_led_v1(p_tenant_id uuid,p_slide_type text,p_orientation text,p_config jsonb)
 returns void language plpgsql stable security definer set search_path='' as $$
declare seed jsonb:=p_config->'seed';families jsonb;
begin
 if p_config is null or pg_column_size(p_config)>524288 or not extensions.jsonb_matches_schema(private.sync_dynamic_configuration_schema_v1()::json,p_config)
 then raise exception 'Source dynamic configuration invalid'using errcode='23514';end if;
 families:=case when p_config->>'rendererVersion'='sync-onzetrots-v1'then private.sync_onzetrots_families_v1()else private.sync_dynamic_families_v1()end;
 if p_config->>'slideType'is distinct from p_slide_type or seed->>'orientation'is distinct from p_orientation
  or not exists(select 1 from jsonb_array_elements_text(families->p_slide_type)family where family=seed->>'family')
  or seed->>'rendererVersion'is distinct from p_config->>'rendererVersion' or seed->>'sourceRevision'is distinct from p_config->>'sourceRevision'
  or length(btrim(seed->>'name'))not between 2 and 120
  or seed->'rows'<>'[]'::jsonb or seed->'news'<>'[]'::jsonb or seed->'ownRowIndexes'<>'[]'::jsonb
  or seed?'home'or seed?'away'or seed?'match'or seed?'poll'or seed?'youtubeUrl'or seed->>'state'<>'ready'
  or(seed?'rich'and seed->'rich'<>'{}'::jsonb)
 then raise exception 'Source dynamic scope or facts invalid'using errcode='23514';end if;
 perform private.assert_sync_slide_v1(p_tenant_id,seed);
end;$$;

alter function private.sync_slide_page_count_v1(jsonb)rename to sync_slide_page_count_before_onzetrots_v1;
create function private.sync_slide_page_count_v1(p_slide jsonb)returns integer
language plpgsql immutable security invoker set search_path=''as $$
declare family text:=p_slide->>'family';count_items integer;capacity integer:=coalesce((p_slide->>'rowsPerPage')::integer,6);
begin
 if p_slide->>'rendererVersion'is distinct from'sync-onzetrots-v1'then return private.sync_slide_page_count_before_onzetrots_v1(p_slide);end if;
 if family in('standings','period-standings','matchday','visitors','welcome')then return 1;end if;
 count_items:=jsonb_array_length(p_slide->'rows');
 if family='birthdays'then count_items:=coalesce(jsonb_array_length(p_slide#>'{rich,birthdays}'),count_items);capacity:=6;
 elsif family in('activities','agenda')then count_items:=coalesce(jsonb_array_length(p_slide#>'{rich,activities}'),count_items);capacity:=6;
 elsif family in('rss','club-story')and p_slide#>'{rich,news}'is not null then return greatest(1,jsonb_array_length(p_slide#>'{rich,news}'));
 elsif family='menu'then capacity:=10;
 elsif family='sponsors'then count_items:=coalesce(jsonb_array_length(p_slide#>'{rich,sponsors}'),count_items);capacity:=6;
 elsif family in('fixtures','club-program','team-program','pool-program','results','club-results','team-results','pool-results')then count_items:=coalesce(jsonb_array_length(p_slide#>'{rich,fixtures}'),count_items);capacity:=case when p_slide->>'orientation'='portrait'then 5 else 6 end;
 elsif p_slide#>'{rich,infoRows}'is not null then count_items:=jsonb_array_length(p_slide#>'{rich,infoRows}');
 elsif p_slide#>'{rich,fixtures}'is not null then count_items:=jsonb_array_length(p_slide#>'{rich,fixtures}');capacity:=case when p_slide->>'orientation'='portrait'then 5 else 6 end;
 else return private.sync_slide_page_count_before_onzetrots_v1(p_slide);end if;
 return greatest(1,ceil(count_items::numeric/capacity)::integer);
end;$$;
create function private.sync_slide_minimum_duration_ms_v1(p_slide jsonb)returns integer
language plpgsql immutable security invoker set search_path=''as $$
declare pages integer:=private.sync_slide_page_count_v1(p_slide);rows integer;row_height integer;viewport integer;speed integer;range integer;minimum_ms numeric:=3000;portrait boolean:=p_slide->>'orientation'='portrait';dashboard boolean:=p_slide->>'family'='matchday';
begin
 if p_slide->>'rendererVersion'='sync-onzetrots-v1'and p_slide->>'family'in('standings','period-standings','matchday')then
  rows:=case when dashboard then coalesce(jsonb_array_length(p_slide#>'{rich,matchday,standings,rows}'),0)else coalesce(jsonb_array_length(p_slide#>'{rich,standings,rows}'),jsonb_array_length(p_slide->'rows'))end;
  row_height:=case when dashboard then case when portrait then 78 else 67 end else case when portrait then 100 else 72 end end;
  viewport:=case when dashboard then case when portrait then 646 else 527 end else case when portrait then 1193 else 524 end end;
  speed:=case p_slide#>>'{visual,scrollSpeed}'when'slow'then 19 when'fast'then 48 else 30 end;
  range:=greatest(0,rows*row_height-viewport);
  if range>0 then minimum_ms:=ceil(5000+2000*range::numeric/speed);end if;
 end if;
 return pages*ceil(minimum_ms/1000)::integer*1000;
end;$$;

