-- Remaining canonical source builder and compatibility definitions follow.

-- A fixture contains normalized facts and provider-cache IDs, never external
-- image URLs. Club membership is derived from the controlled source's active
-- team relation, not is_home_match, a display name or a browser assertion.
create function private.sync_onzetrots_fixture_v1(fixture public.sports_matches,own_club_id text)returns jsonb
language sql stable security invoker set search_path=''as $$
 select jsonb_strip_nulls(jsonb_build_object(
  'id',fixture.external_id,'primary',concat_ws(' – ',fixture.home_team->>'name',fixture.away_team->>'name'),
  'homeTeam',fixture.home_team->>'name','awayTeam',fixture.away_team->>'name',
  'homeTeamId',fixture.home_team->>'externalId','awayTeamId',fixture.away_team->>'externalId',
  'homeClubId',case when exists(select 1 from public.sports_teams team where team.tenant_id=fixture.tenant_id and team.source_connection_id=fixture.source_connection_id and team.active and team.external_id=fixture.home_team->>'externalId')then own_club_id end,
  'awayClubId',case when exists(select 1 from public.sports_teams team where team.tenant_id=fixture.tenant_id and team.source_connection_id=fixture.source_connection_id and team.active and team.external_id=fixture.away_team->>'externalId')then own_club_id end,
  'homeLogoMediaAssetId',(select cache.current_version_id from public.provider_asset_cache cache where cache.provider='sportlink'and cache.entity_type='team'and cache.asset_role='team_logo'and cache.external_entity_id=fixture.home_team->>'externalId'),
  'awayLogoMediaAssetId',(select cache.current_version_id from public.provider_asset_cache cache where cache.provider='sportlink'and cache.entity_type='team'and cache.asset_role='team_logo'and cache.external_entity_id=fixture.away_team->>'externalId'),
  'homeScore',case when fixture.scores_published then fixture.home_team->'score'else null end,
  'awayScore',case when fixture.scores_published then fixture.away_team->'score'else null end,
  'kickoffAt',fixture.starts_at,'kickoffTime',to_char(fixture.starts_at at time zone'Europe/Amsterdam','HH24:MI'),
  'date',to_char(fixture.starts_at at time zone'Europe/Amsterdam','DD-MM-YYYY'),'time',to_char(fixture.starts_at at time zone'Europe/Amsterdam','HH24:MI'),
  'status',fixture.status,'field',fixture.venue->>'field','venueName',fixture.venue->>'name',
  'homeRoom',fixture.dressing_rooms->>'home','awayRoom',fixture.dressing_rooms->>'away',
  'homeMatch',exists(select 1 from public.sports_teams team where team.tenant_id=fixture.tenant_id and team.source_connection_id=fixture.source_connection_id and team.active and team.external_id=fixture.home_team->>'externalId')
 ))
$$;

alter function private.build_dynamic_snapshot_data(public.dynamic_slides)rename to build_dynamic_snapshot_before_onzetrots_v1;
create function private.build_dynamic_snapshot_data(p_slide public.dynamic_slides)returns jsonb
language plpgsql stable security definer set search_path=''as $$
declare result jsonb;connection_id uuid;own_club_id text;own_teams jsonb;selection jsonb;resolved_selection jsonb;
 context jsonb;resolved_context jsonb;scope jsonb;scope_context jsonb;standing public.sports_standings%rowtype;
 standing_identity jsonb;standing_items jsonb;fixture_items jsonb;result_items jsonb;dataset_revision bigint;ctx jsonb;rich_matchday jsonb;
begin
 if p_slide.configuration_json#>>'{syncConfiguration,rendererVersion}'is distinct from'sync-onzetrots-v1'then return private.build_dynamic_snapshot_before_onzetrots_v1(p_slide);end if;
 perform private.assert_sync_dynamic_configuration_v1(p_slide.tenant_id,p_slide.slide_type,p_slide.orientation,p_slide.configuration_json->'syncConfiguration');
 result:=private.build_dynamic_snapshot_before_onzetrots_v1(p_slide);
 if p_slide.slide_type not like'sport\_%'escape'\'then return result;end if;
 select connection.id into strict connection_id from public.sportlink_connections connection where connection.tenant_id=p_slide.tenant_id and connection.data_source_id=p_slide.data_source_id and connection.status='active';
 select case when count(*)=1 then min(club.external_id)end into own_club_id from public.sports_clubs club where club.tenant_id=p_slide.tenant_id and club.source_connection_id=connection_id and club.active;
 selection:=coalesce(p_slide.configuration_json->'sourceTeamSelection',p_slide.configuration_json->'teamSelection',jsonb_build_object('mode','selected','teamContexts',coalesce(p_slide.configuration_json->'teamContexts',jsonb_build_array(p_slide.configuration_json->'context'))));
 if p_slide.slide_type in('sport_activities','sport_volunteers')then selection:=jsonb_build_object('mode','all','teamContexts','[]'::jsonb);end if;
 if p_slide.slide_type='sport_birthdays'then selection:=jsonb_build_object('mode','all','teamContexts','[]'::jsonb);end if;
 if not private.sportlink_team_selection_is_valid_v1(p_slide.tenant_id,p_slide.data_source_id,selection)then raise exception 'Approved source team selection invalid'using errcode='23514';end if;
 resolved_selection:=private.resolve_sportlink_match_selection_v1(p_slide.tenant_id,p_slide.data_source_id,selection);
 select coalesce(jsonb_agg(team.external_id order by team.external_id),'[]'::jsonb)into own_teams from public.sports_teams team where team.tenant_id=p_slide.tenant_id and team.source_connection_id=connection_id and team.active and(selection->>'mode'='all'or exists(select 1 from jsonb_array_elements(selection->'teamContexts')item where item->>'providerTeamId'=team.external_id));
 if jsonb_array_length(own_teams)>200 then raise exception 'Approved source selection exceeds 200 teams'using errcode='23514';end if;
 context:=p_slide.configuration_json->'context';
 if context is not null and context<>'null'::jsonb then
  if not private.sportlink_team_contexts_are_valid_v2(p_slide.tenant_id,p_slide.data_source_id,jsonb_build_array(context))then raise exception 'Approved source context invalid'using errcode='23514';end if;
  resolved_context:=private.resolve_sportlink_pool_context_v1(p_slide.tenant_id,p_slide.data_source_id,context,'sportlink.pool_standings');
  if resolved_context is not null then scope_context:=jsonb_build_object('teamId',context->>'providerTeamId','competitionId',resolved_context->>'competitionId','poolId',resolved_context->>'poolId','seasonId',resolved_context->>'seasonId');end if;
 end if;
 scope:=jsonb_build_object('schemaVersion',1,'tenantId',p_slide.tenant_id,'sourceId',p_slide.data_source_id,'sourceConnectionId',connection_id,'ownClubId',own_club_id,'ownTeamIds',own_teams,'context',scope_context);
 result:=result||jsonb_build_object('syncScope',scope);

 if p_slide.slide_type in('sport_standing','sport_period_standing','sport_match_of_the_day')then
  if resolved_context is null then raise exception 'Select a published team competition, pool and season for this OnzeTrots design'using errcode='23514';end if;
  standing_identity:=private.resolve_sportlink_standing_team_identity_v1(p_slide.tenant_id,connection_id,context->>'providerTeamId');
  select candidate.*into standing from public.sports_standings candidate where candidate.tenant_id=p_slide.tenant_id and candidate.source_connection_id=connection_id and candidate.active and candidate.scores_published
   and coalesce(candidate.metadata#>>'{pool,externalId}',candidate.metadata#>>'{pool,poolExternalId}',candidate.pool_external_id)=resolved_context->>'poolId'
   and private.sportlink_competition_identity_v1(candidate.metadata->'competition',candidate.metadata->'pool')is not distinct from resolved_context->>'competitionId'
   and candidate.season_key is not distinct from resolved_context->>'seasonId'
   and(case when p_slide.slide_type='sport_period_standing'then candidate.period_number is not null else candidate.period_number is null end)
   and(resolved_context->>'phaseId'is null or candidate.metadata#>>'{competition,period}'=resolved_context->>'phaseId')
   and exists(select 1 from jsonb_array_elements(candidate.rows_json)row where private.sportlink_standing_row_matches_team_v1(row,standing_identity))
  order by candidate.last_synced_at desc,candidate.id limit 1;
  select coalesce(jsonb_agg(row||jsonb_strip_nulls(jsonb_build_object(
   'id',row->>'externalId','teamId',case when private.sportlink_standing_row_matches_team_v1(row,standing_identity)then context->>'providerTeamId'when row->>'externalId'!~'^[a-f0-9]{64}$'then row->>'externalId'end,
   'clubId',case when private.sportlink_standing_row_matches_team_v1(row,standing_identity)then own_club_id end,
   'logoMediaAssetId',(select cache.current_version_id from public.provider_asset_cache cache where cache.provider='sportlink'and cache.entity_type='team'and cache.asset_role='team_logo'and cache.external_entity_id=case when private.sportlink_standing_row_matches_team_v1(row,standing_identity)then context->>'providerTeamId'else row->>'externalId'end),
   'selected',private.sportlink_standing_row_matches_team_v1(row,standing_identity)
  ))order by (row->>'position')::integer nulls last,row->>'externalId'),'[]'::jsonb)into standing_items from jsonb_array_elements(coalesce(standing.rows_json,'[]'::jsonb))row;
  if jsonb_array_length(standing_items)>200 then raise exception 'Approved full standings exceeds 200 rows'using errcode='23514';end if;
  if p_slide.slide_type<>'sport_match_of_the_day'then result:=jsonb_set(result,'{sport,items}',standing_items);end if;
 end if;

 if p_slide.slide_type='sport_visitor_arrivals'and p_slide.configuration_json#>>'{syncConfiguration,seed,family}'in('welcome','visitors')then
  if own_club_id is null or selection->>'mode'<>'selected'or jsonb_array_length(own_teams)=0 then raise exception 'Approved welcome needs a controlled club and explicit home teams'using errcode='23514';end if;
  select coalesce(jsonb_agg(private.sync_onzetrots_fixture_v1(fixture,own_club_id)order by fixture.starts_at,fixture.external_id),'[]'::jsonb)into fixture_items from(
   select match.*from public.sports_matches match where match.tenant_id=p_slide.tenant_id and match.source_connection_id=connection_id and match.active and match.status='scheduled'and match.starts_at>now()and(match.expires_at is null or match.expires_at>now())
    and own_teams? (match.home_team->>'externalId')and private.sportlink_match_matches_resolved_selection_v1(match,resolved_selection)
   order by match.starts_at,match.external_id limit 4
  )fixture;
  result:=jsonb_set(result,'{sport,items}',fixture_items);
 elsif p_slide.slide_type='sport_match_of_the_day'then
  if scope_context->>'competitionId'is null or scope_context->>'poolId'is null or scope_context->>'seasonId'is null then raise exception 'Complete matchday competition, pool and season required'using errcode='23514';end if;
  -- One canonical read in the current snapshot transaction. Each component
  -- carries that same pinned identity and its source-observation revision.
  select coalesce(jsonb_agg(private.sync_onzetrots_fixture_v1(match,own_club_id)order by match.starts_at desc,match.external_id)filter(where match.status='finished'),'[]'::jsonb),
   coalesce(jsonb_agg(private.sync_onzetrots_fixture_v1(match,own_club_id)order by match.starts_at,match.external_id)filter(where match.status='scheduled'and match.starts_at>now()),'[]'::jsonb),
   coalesce(floor(extract(epoch from max(match.last_synced_at))*1000)::bigint,0)
   into result_items,fixture_items,dataset_revision
  from public.sports_matches match where match.tenant_id=p_slide.tenant_id and match.source_connection_id=connection_id and match.active and match.scores_published and(match.expires_at is null or match.expires_at>now())
   and private.sportlink_competition_identity_v1(match.competition,match.pool)=scope_context->>'competitionId'
   and coalesce(match.pool->>'externalId',match.pool->>'poolExternalId')=scope_context->>'poolId'
   and match.competition->>'season'=scope_context->>'seasonId'
   and(resolved_context->>'phaseId'is null or match.competition->>'period'=resolved_context->>'phaseId')
   and match.status in('finished','scheduled');
  if jsonb_array_length(result_items)>200 or jsonb_array_length(fixture_items)>200 then raise exception 'Complete matchday selection exceeds 200 records'using errcode='23514';end if;
  ctx:=scope_context||jsonb_build_object('tenantId',p_slide.tenant_id);
  rich_matchday:=jsonb_build_object(
   'context',ctx||jsonb_build_object('revisions',jsonb_build_array(jsonb_build_object('dataset','results','revision',dataset_revision),jsonb_build_object('dataset','standings','revision',coalesce(floor(extract(epoch from standing.last_synced_at)*1000)::bigint,0)),jsonb_build_object('dataset','fixtures','revision',dataset_revision))),
   'results',jsonb_build_object('context',ctx,'items',result_items),
   'standings',jsonb_build_object('context',ctx,'items',standing_items),
   'fixtures',jsonb_build_object('context',ctx,'items',fixture_items));
  result:=jsonb_set(result,'{sport,matchday}',rich_matchday);
 elsif p_slide.slide_type in('sport_program','sport_results','sport_next_match','sport_dressing_rooms','sport_cancellations','sport_visitor_arrivals')then
  -- Enrich only the authorized records selected by the established blueprint;
  -- retain its date, team, cancellation and privacy filters without widening.
  select coalesce(jsonb_agg(item.value||private.sync_onzetrots_fixture_v1(match,own_club_id)order by item.ordinality),'[]'::jsonb)into fixture_items
  from jsonb_array_elements(coalesce(result#>'{sport,items}','[]'::jsonb))with ordinality item(value,ordinality)
  join public.sports_matches match on match.tenant_id=p_slide.tenant_id and match.source_connection_id=connection_id and match.external_id=item.value->>'id'and match.active;
  result:=jsonb_set(result,'{sport,items}',fixture_items);
 end if;
 return result;
end;$$;

