begin
 for proc in select p.oid from pg_proc p join pg_namespace n on n.oid=p.pronamespace where
  (n.nspname='public'and p.proname='list_publisher_sync_studio_v1')
  or(n.nspname='private'and p.proname in('s226_conflict_base_prepare_publisher_sync_project_v1','s226_conflict_base_mutate_sync_studio_series_v1','s226_conflict_base_mutate_playlist_batch_v1'))
 loop
  definition:=pg_get_functiondef(proc.oid);updated:=definition;
  updated:=regexp_replace(updated,$pattern$([a-z_.]+)#>>'\{syncPresentation,rendererVersion\}'[[:space:]]*=[[:space:]]*'sync-v1'[[:space:]]+and[[:space:]]+\1#>>'\{syncPresentation,sourceRevision\}'[[:space:]]*=[[:space:]]*'8b1fdf1f8637dda23d48ecdaf08e0e5978e2707a'$pattern$,
   $replacement$private.sync_presentation_identity_is_valid_v2(\1#>>'{syncPresentation,rendererVersion}',\1#>>'{syncPresentation,sourceRevision}')$replacement$,'g');
  updated:=regexp_replace(updated,$pattern$([a-z_.]+)#>>'\{syncPresentation,rendererVersion\}'[[:space:]]+is distinct from[[:space:]]+'sync-v1'[[:space:]]+or[[:space:]]+\1#>>'\{syncPresentation,sourceRevision\}'[[:space:]]+is distinct from[[:space:]]+'8b1fdf1f8637dda23d48ecdaf08e0e5978e2707a'$pattern$,
   $replacement$not private.sync_presentation_identity_is_valid_v2(\1#>>'{syncPresentation,rendererVersion}',\1#>>'{syncPresentation,sourceRevision}')$replacement$,'g');
  updated:=regexp_replace(updated,$pattern$([a-z_.]+)#>>'\{syncPresentation,rendererVersion\}'[[:space:]]*=[[:space:]]*'sync-v1'$pattern$,
   $replacement$private.sync_presentation_identity_is_valid_v2(\1#>>'{syncPresentation,rendererVersion}',\1#>>'{syncPresentation,sourceRevision}')$replacement$,'g');
  if updated=definition then raise exception 'Approved active Sync gate precondition failed: %',proc.oid::regprocedure;end if;
  execute updated;
 end loop;
 -- Only new rich facts may differ from the fact-free frozen seed. Validate
 -- every nested asset against typed canonical fields and the immutable checksum.
 definition:=pg_get_functiondef('private.assert_sync_dynamic_render_presentation_v1(public.dynamic_slide_snapshots,jsonb)'::regprocedure);
 if position('array[''rows'',''news'',''ownRowIndexes'',''home'',''away'',''match'',''state'',''club'']'in definition)=0 then raise exception 'Approved dynamic render gate precondition failed';end if;
 definition:=replace(definition,'array[''rows'',''news'',''ownRowIndexes'',''home'',''away'',''match'',''state'',''club'']','array[''rows'',''news'',''ownRowIndexes'',''home'',''away'',''match'',''state'',''club'',''rich'']');
 definition:=replace(definition,'clean jsonb:=p_presentation','clean jsonb:=(p_presentation-''rich'')');
 definition:=replace(definition,' if p_presentation is null', $scope$
 if p_presentation->>'rendererVersion'='sync-onzetrots-v1'then
  if p_presentation#>'{rich,teamSelection}'is not null and p_presentation#>'{rich,teamSelection}'is distinct from jsonb_build_object('ownClubId',p_snapshot.snapshot_data_json#>'{syncScope,ownClubId}','ownTeamIds',p_snapshot.snapshot_data_json#>'{syncScope,ownTeamIds}','primaryTeamId',p_snapshot.snapshot_data_json#>'{syncScope,context,teamId}')then raise exception 'Approved team selection differs from canonical source'using errcode='23514';end if;
  if(p_presentation#>'{rich,standings}'is not null and p_presentation#>'{rich,standings,ownTeamId}'is distinct from coalesce(p_snapshot.snapshot_data_json#>'{syncScope,context,teamId}','null'::jsonb))or(p_presentation#>'{rich,matchday,standings}'is not null and p_presentation#>'{rich,matchday,standings,ownTeamId}'is distinct from coalesce(p_snapshot.snapshot_data_json#>'{syncScope,context,teamId}','null'::jsonb))then raise exception 'Approved own standing row differs from canonical team'using errcode='23514';end if;
  if p_presentation#>'{rich,visitorsSelection}'is not null and(p_presentation#>'{rich,visitorsSelection,ownClubId}'is distinct from p_snapshot.snapshot_data_json#>'{syncScope,ownClubId}'or p_presentation#>'{rich,visitorsSelection,ownTeamIds}'is distinct from p_snapshot.snapshot_data_json#>'{syncScope,ownTeamIds}')then raise exception 'Approved welcome differs from canonical home selection'using errcode='23514';end if;
  if p_presentation#>'{rich,matchday}'is not null and(p_presentation#>>'{rich,matchday,context,tenantId}'is distinct from p_snapshot.tenant_id::text or((p_presentation#>'{rich,matchday,context}')-array['tenantId','revisions'])is distinct from p_snapshot.snapshot_data_json#>'{syncScope,context}')then raise exception 'Approved matchday differs from canonical tenant/team/pool/season'using errcode='23514';end if;
 end if;
 if p_presentation is null$scope$);

 definition:=replace(definition,')item(role,asset)where item.asset is not null loop',')item(role,asset)where item.asset is not null union all select ''nested'',value from private.sites_asset_references_v1(p_presentation->''rich'') value loop');
 execute definition;
 -- Do not allow a new renderer marker through the generic, untyped authoring route.
 definition:=pg_get_functiondef('private.json_has_sites_authoring_v1(jsonb)'::regprocedure);
 if position('''sync-v1'''in definition)=0 then raise exception 'Approved generic authoring fence precondition failed';end if;
 execute replace(definition,'''sync-v1''','''sync-v1'',''sync-onzetrots-v1''');
end;$migration$;

alter table public.playlist_release_items drop constraint playlist_release_items_sync_studio_check;
alter table public.playlist_release_items add constraint playlist_release_items_sync_studio_check check(
 (sync_studio_presentation_json is null and sync_studio_duration_ms is null)or
 (sync_studio_presentation_json is not null and sync_studio_duration_ms is not null and sites_studio_presentation_json is null
  and sync_studio_duration_ms between 3000 and 120000 and jsonb_typeof(sync_studio_presentation_json)='object'
  and sync_studio_presentation_json->>'schemaVersion'='1'
  and private.sync_presentation_identity_is_valid_v2(sync_studio_presentation_json->>'rendererVersion',sync_studio_presentation_json->>'sourceRevision')
  and pg_column_size(sync_studio_presentation_json)<=524288)
);

revoke all on function private.sync_onzetrots_image_manifest_v1(),private.sync_onzetrots_background_manifest_v1(),private.sync_onzetrots_families_v1(),
 private.sync_presentation_identity_is_valid_v2(text,text),private.assert_sync_slide_before_onzetrots_v1(uuid,jsonb),private.assert_sync_slide_before_youtube_v1(uuid,jsonb),
 private.sync_slide_page_count_before_onzetrots_v1(jsonb),private.sync_slide_page_count_v1(jsonb),private.sync_slide_minimum_duration_ms_v1(jsonb),
 private.sync_slide_duration_ms_v1(jsonb,integer),private.sync_slide_internal_motion_v1(jsonb),private.sync_onzetrots_fixture_v1(public.sports_matches,text),private.build_dynamic_snapshot_before_onzetrots_v1(public.dynamic_slides),private.build_dynamic_snapshot_data(public.dynamic_slides)
 from public,anon,authenticated,service_role;
notify pgrst,'reload schema';
commit;
